import{z as o,x as i,o as A,c as l,q as B,j as r,D as a,d as t,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"审计准备","description":"","frontmatter":{"title":"审计准备","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-audit-preparedness.md","filePath":"quant/qo-audit-preparedness.md","lastUpdated":1791063341000}'),D={name:"quant/qo-audit-preparedness.md"};function d(F,E,p,u,C,h){const e=i("Mermaid");return A(),l("div",null,[E[2]||(E[2]=B('<h1 id="审计准备" tabindex="-1">审计准备 <a class="header-anchor" href="#审计准备" aria-label="Permalink to &quot;审计准备&quot;">​</a></h1><div class="epigraph"><p>审计不是一场考试，而是一种状态：任何一条昨天的记录，今天必须原样可取。</p><footer>—— 据 Federal Reserve SR 11-7（2011）与公开监管检查口径整理</footer></div><p><a href="/quant/qo-reporting-obligations">上一课</a>把记录按监管口径出口；审计要求每一条出口都能<strong>反查回源头</strong>。<a href="/quant/sl-map">策略生命周期治理收束</a>立过七条不变量——追加不改写、仓位可沿指针链反查；<a href="/quant/sr-11-7-model-risk">SR 11-7</a>写过模型治理的预期，<a href="/quant/fml-audit">ML 审计</a>写过模型侧的可审计对象；本课写机构侧：审计有哪些对象、留痕靠什么维持、检查来了怎么应答。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>审计被当成事件突击，是最贵的准备方式：检查通知到位再翻记录，翻不到的补不出来，补出来的互相矛盾。缺口的状态学有三层：<strong>记录存在但不可取</strong>——数据在，调取要跨系统拼一周，赶不上时限；<strong>可取但不可信</strong>——记录事后可改，没有追加不改写的机制约束，证据力归零；<strong>可信但串不起来</strong>——交易、审批、参数变更、通讯各自留痕，但某笔仓位为什么在跑，四条链接不到一起。审计准备的全部内容，就是把这三层提前修好，让「状态」不依赖「事件」。</p><p><span class="marginnote">直觉类比：三层缺口像三种借不到的书——书在库房但没有架位索引（不可取）；有索引但书页能私下涂改（不可信）；每页都在但缺了目录，拼不成一段完整论证（串不起来）。三样都修好，任何一天来查都一样，这才叫状态。</span></p>',6)),(A(),r(n,null,{default:a(()=>[s(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%EF%BC%9A%E8%AE%B0%E5%BD%95%E5%AD%98%E5%9C%A8%E4%BD%86%E4%B8%8D%E5%8F%AF%E5%8F%96%22%5D%20--%3E%20FIX1%5B%22%E4%BF%AE%E7%B4%A2%E5%BC%95%E5%B1%82%EF%BC%9A%E6%8C%89%E4%BB%93%E4%BD%8D%20%2F%20%E7%AD%96%E7%95%A5%20%2F%20%E6%97%A5%E6%9C%9F%E7%9B%B4%E6%8E%A5%E5%91%BD%E4%B8%AD%22%5D%0A%20%20L2%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%EF%BC%9A%E5%8F%AF%E5%8F%96%E4%BD%86%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%20--%3E%20FIX2%5B%22%E4%BF%AE%E5%8F%AA%E8%BF%BD%E5%8A%A0%E5%AD%98%E5%82%A8%EF%BC%9A%E6%9B%B4%E6%AD%A3%E4%BB%A5%E6%96%B0%E8%AE%B0%E5%BD%95%E5%87%BA%E7%8E%B0%EF%BC%8C%E5%8E%9F%E8%AE%B0%E5%BD%95%E4%BF%9D%E7%95%99%22%5D%0A%20%20L3%5B%22%E7%AC%AC%E4%B8%89%E5%B1%82%EF%BC%9A%E5%8F%AF%E4%BF%A1%E4%BD%86%E4%B8%B2%E4%B8%8D%E8%B5%B7%E6%9D%A5%22%5D%20--%3E%20FIX3%5B%22%E4%BF%AE%E8%AF%81%E6%8D%AE%E9%93%BE%EF%BC%9A%E4%BA%A4%E6%98%93-%E5%AE%A1%E6%89%B9-%E5%8F%82%E6%95%B0-%E9%80%9A%E8%AE%AF%E6%8E%A5%E5%88%B0%E5%90%8C%E4%B8%80%E4%BB%93%E4%BD%8D%22%5D%0A%20%20FIX1%20--%3E%20ST%5B%22%E5%AE%A1%E8%AE%A1%E5%87%86%E5%A4%87%E6%88%90%E4%B8%BA%E7%8A%B6%E6%80%81%EF%BC%8C%E4%B8%8D%E9%9D%A0%E7%AA%81%E5%87%BB%22%5D%0A%20%20FIX2%20--%3E%20ST%0A%20%20FIX3%20--%3E%20ST%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先分对象，再配留痕，最后演练。<strong>对象四类</strong>：财务审计盯估值与净值——托管复核链见<a href="/quant/cn-custody-counter">托管与柜台</a>；监管检查盯合规义务的履行证据——监控告警的处理记录、报备与速率画像的勾稽、训练与演练记录；内部审计与模型验证盯模型生命周期——验证报告、假设清单、使用范围，按 <a href="/quant/sr-11-7-model-risk">SR 11-7</a> 的相称性配置深度；客户尽调（DDQ）盯同一套材料的对外版本。<strong>留痕清单</strong>：交易与订单记录（含被拒单）、审批链（谁在何时以何判据批准）、参数与权限变更、受控通讯归档。<strong>演练</strong>：定期做模拟调档——随机抽一个已平仓仓位、一次限额变更、一次告警，计时「多久能给出完整证据链」；目标与<a href="/quant/sl-map">生命周期治理收束</a>的自检同口径：五分钟答出凭什么。</p><p><span class="marginnote">数字实例：演练可以这样计时——随机抽一笔三个月前已平仓的仓位，从提问到交出「交易单、审批人、当时参数、相关通讯」四件套，超过五分钟算不合格。这个标准不是摆设：监管问询的反馈时限通常以小时计，临时拼数据的团队必输。</span></p>',3)),(A(),r(n,null,{default:a(()=>[s(e,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%AE%A1%E8%AE%A1%E6%88%96%E6%A3%80%E6%9F%A5%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20IDX%5B%22%E7%B4%A2%E5%BC%95%E5%B1%82%EF%BC%9A%E6%8C%89%E4%BB%93%E4%BD%8D%20%2F%20%E7%AD%96%E7%95%A5%20%2F%20%E6%97%A5%E6%9C%9F%E8%B0%83%E5%8F%96%22%5D%0A%20%20IDX%20--%3E%20T1%5B%22%E4%BA%A4%E6%98%93%E4%B8%8E%E8%AE%A2%E5%8D%95%E8%AE%B0%E5%BD%95%EF%BC%9A%E5%90%AB%E8%A2%AB%E6%8B%92%E5%8D%95%22%5D%0A%20%20IDX%20--%3E%20T2%5B%22%E5%AE%A1%E6%89%B9%E9%93%BE%EF%BC%9A%E5%88%A4%E6%8D%AE%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20IDX%20--%3E%20T3%5B%22%E5%8F%82%E6%95%B0%E4%B8%8E%E6%9D%83%E9%99%90%E5%8F%98%E6%9B%B4%E6%97%A5%E5%BF%97%22%5D%0A%20%20IDX%20--%3E%20T4%5B%22%E5%8F%97%E6%8E%A7%E9%80%9A%E8%AE%AF%E5%BD%92%E6%A1%A3%22%5D%0A%20%20T1%20--%3E%20ASM%5B%22%E8%AF%81%E6%8D%AE%E9%93%BE%E6%8B%BC%E8%A3%85%EF%BC%9A%E4%BB%93%E4%BD%8D%E5%88%B0%E5%88%A4%E6%8D%AE%E5%88%B0%E4%BA%BA%22%5D%0A%20%20T2%20--%3E%20ASM%0A%20%20T3%20--%3E%20ASM%0A%20%20T4%20--%3E%20ASM%0A%20%20ASM%20--%3E%20TM%7B%22%E6%97%B6%E9%99%90%E5%86%85%E4%BA%A4%E4%BB%98%3F%22%7D%0A%20%20TM%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E4%BA%A4%E4%BB%98%E5%B9%B6%E7%95%99%E8%B0%83%E5%8F%96%E8%AE%B0%E5%BD%95%22%5D%0A%20%20TM%20--%3E%7C%22%E5%90%A6%22%7C%20GAP%5B%22%E7%BC%BA%E5%8F%A3%E7%99%BB%E8%AE%B0%EF%BC%9A%E8%A1%A5%E6%9C%BA%E5%88%B6%E4%B8%8D%E8%A1%A5%E8%AE%B0%E5%BD%95%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么「追加不改写」是全部机制的核心：审计的本质是<strong>过去不可变</strong>。一份事后能改的记录，无论存了多少份，证明力都是零；所以留痕必须落在只追加的存储上，更正以新记录形式出现并保留原记录——这与报告纠错的回填留痕、<a href="/quant/sl-registry">策略台账体系</a>的台账纪律是同一条不变量在不同对象上的实例。为什么索引层值得单独建设：记录散在四个系统里不算可取，调取能力是「按仓位、按策略、按日期」三个维度直接命中的能力；没有索引层，每次检查都是一次人肉数据工程。为什么缺口要登记成机制改进：演练暴露的缺口只补这一次的记录，等于每次检查都从零开始；缺口进<a href="/quant/research-postmortem">研究复盘</a>同模板的归档，下一次演练复测。<a href="/quant/mifid-ii-rts6">MiFID II RTS 6</a>对高频技术订单记录的要求是同一逻辑的极端版：逐笔记录、指定字段、按年保存——记录义务的深度随交易方式的复杂度上升，机制不变。</p><p><span class="marginnote">术语翻译：「追加不改写」（append-only）就是数据库只许插入新行、不许修改或删除旧行。想改数？只能加一行新记录，写明「更正了什么、谁改的」，原行原样留着——就像纸质账本画线更正而不是撕页重写，撕页本身就是问题。</span></p><p><span class="marginnote">调取演练最常暴露的一环不是数据缺失，而是「口径对不上」：交易系统、估值系统、报备系统对同一笔仓位三个数量。证据链拼装的第一步永远是先对平三本账，再回答问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写准备的状态，不写应答的策略：对抗性应对、选择性提供、口头补充解释都是自伤——检查语境下，取不出的记录按不存在处理，比慢更糟。法律意见边界同前两课。模型验证的技术细节见 <a href="/quant/sr-11-7-model-risk">SR 11-7</a> 与 <a href="/quant/fml-audit">ML 审计</a>，台账与判据的治理结构见<a href="/quant/sl-map">策略生命周期治理</a>课程，本课只接它的不变量，不重写它的内容。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>审计准备是状态不是事件：记录可取、可信、可串成证据链，三层都要提前修。</li><li>对象四类：财务审计、监管检查、内部审计与模型验证、客户尽调，共用一套留痕。</li><li>核心不变量是追加不改写：更正以新记录出现，原记录永留。</li><li>索引层决定调取能力：按仓位、策略、日期三维命中，模拟调档计时验收。</li><li>出处：据 Federal Reserve SR 11-7（2011）与 RTS 6 订单记录条款的公开口径整理；模型侧对象见<a href="/quant/fml-audit">ML 审计</a>。</li></ul>',8))])}const _=o(D,[["render",d]]);export{f as __pageData,_ as default};
